sys_variable_value.value:
(function execute(inputs, outputs) {

outputs.apikey = gs.getProperty("x_1488662_hr_ref_0.refund_apikey", 0);
outputs.base_currency = gs.getProperty("x_1488662_hr_ref_0.refund_base_currency", "");
outputs.currencies = gs.getProperty("x_1488662_hr_ref_0.currencies", "BRL");
outputs.endpoint = gs.getProperty("x_1488662_hr_ref_0.refund_endpoint","");

})(inputs, outputs);
